function doodle(shape: Shape, name: string): Icon {
  const C = ({ className, ...props }: IconProps) => (
    <svg
      viewBox={shape.vb}
      width="1em"
      height="1em"
      fill="currentColor"
      aria-hidden
      focusable="false"
      className={cn("shrink-0", className)}
      {...props}
    >
      {shape.fill?.map((d, i) => (
        <path key={`f${i}`} d={d} fillOpacity={0.26} transform="translate(7 6)" />
      ))}
      {shape.d.map((d, i) => (
        <path key={i} d={d} />
      ))}
    </svg>
  );
  C.displayName = name;
  return C;
}

/** Lijntjes in dezelfde hand: licht golvend, ronde uiteinden. */
function stroke(paths: string[], name: string, vb = "0 0 24 24", width = 2): Icon {
  const C = ({ className, ...props }: IconProps) => (
    <svg
      viewBox={vb}
      width="1em"
      height="1em"
      fill="none"
      stroke="currentColor"
      strokeWidth={width}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
      focusable="false"
      className={cn("shrink-0", className)}
      {...props}
    >
      {paths.map((d, i) => (
        <path key={i} d={d} />
      ))}
    </svg>
  );
  C.displayName = name;
  return C;
}

/** Een letter als icoon, voor de opmaakknoppen in de editor. */
function glyph(text: string, name: string, extra = ""): Icon {
  const C = ({ className }: IconProps) => (
    <span aria-hidden className={cn("inline-flex size-4 shrink-0 items-center justify-center font-sans text-[14px] leading-none", extra, className)}>
      {text}
    </span>
  );
  C.displayName = name;
  return C;
}

